import React, { Component } from 'react';
import { CButton, CCol, CContainer, CRow } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import Plot from 'react-plotly.js';

const FILE_NAME = "WorkReport.js";

function getMonday(dateStr) {
    const d = new Date(dateStr + 'T00:00:00');
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    return formatDateISO(d);
}

function formatDateISO(d) {
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function getWeekDates(mondayStr) {
    const dates = [];
    for (let i = 0; i < 7; i++) {
        const d = new Date(mondayStr + 'T00:00:00');
        d.setDate(d.getDate() + i);
        dates.push(formatDateISO(d));
    }
    return dates;
}

function getMonthDates(yearMonth) {
    // yearMonth = 'YYYY-MM'
    const [year, month] = yearMonth.split('-').map(Number);
    const daysInMonth = new Date(year, month, 0).getDate();
    const dates = [];
    for (let d = 1; d <= daysInMonth; d++) {
        dates.push(`${yearMonth}-${String(d).padStart(2, '0')}`);
    }
    return dates;
}

function getCurrentYearMonth() {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function formatYearMonth(ym) {
    const [year, month] = ym.split('-');
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${monthNames[parseInt(month) - 1]} ${year}`;
}

function getTodayDate() {
    return formatDateISO(new Date());
}

function formatDate(dateStr) {
    const d = new Date(dateStr + 'T00:00:00');
    return d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
}

const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

function timeToMinutes(t) {
    if (!t || t.length !== 4) return 0;
    return parseInt(t.substring(0, 2)) * 60 + parseInt(t.substring(2));
}

function minutesToDisplay(mins) {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

function minutesToHours(mins) {
    return Math.round((mins / 60) * 100) / 100;
}

class WorkReport extends Component {

    constructor(props) {
        super(props);
        this.state = {
            viewMode: 'week', // 'week' or 'month'
            weekStart: getMonday(getTodayDate()),
            monthStart: getCurrentYearMonth(),
            subPrograms: [],
            programs: [],
            persons: [],
            weekData: {},
            isLoaded: false,
            isLoadingWeek: false,
            error: null,
        };
    }

    componentDidMount() {
        document.title = "Work Report";
        this.fetchReferenceData().then(() => this.fetchPeriodData());
    }

    fetchReferenceData = () => {
        const userData = getUserDataFromLocalStorage();
        const subProgramPayload = JSON.stringify({ size: 0 });
        const programPayload = JSON.stringify({ size: 0, type: 'WORK' });
        const personPayload = JSON.stringify({ size: 0 });

        return Promise.all([
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list', requestHeaderPOSTWithAuth(subProgramPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list', requestHeaderPOSTWithAuth(programPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/person/list', requestHeaderPOSTWithAuth(personPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
        ])
        .then(([subProgramsResult, programsResult, personsResult]) => {
            const programs = (programsResult && programsResult.data) || [];
            const programIds = new Set(programs.map(p => p.id));
            const allSubPrograms = (subProgramsResult && subProgramsResult.data) || [];
            const subPrograms = allSubPrograms.filter(sp => programIds.has(sp.programId));
            this.setState({
                subPrograms,
                programs,
                persons: (personsResult && personsResult.data) || [],
                isLoaded: true,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchReferenceData", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    fetchPeriodData = () => {
        const { viewMode, weekStart, monthStart } = this.state;
        const dates = viewMode === 'month' ? getMonthDates(monthStart) : getWeekDates(weekStart);
        const userData = getUserDataFromLocalStorage();

        this.setState({ isLoadingWeek: true });

        const fetchDay = (date) =>
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/day?date=' + date, requestHeaderGETWithAuth(userData.authToken))
                .then(response => {
                    if (response.status === 200) return response.json();
                    if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
                    throw new Error("HTTP " + response.status);
                })
                .then(result => ({ date, logs: result.data || [] }))
                .catch(() => ({ date, logs: [] }));

        Promise.all(dates.map(fetchDay))
            .then(results => {
                const weekData = {};
                results.forEach(r => { weekData[r.date] = r.logs; });
                this.setState({ weekData, isLoadingWeek: false });
            })
            .catch(error => {
                Logger(FILE_NAME, "fetchPeriodData", "ERROR", "error", error);
                this.setState({ isLoadingWeek: false, error: error.message });
            });
    }

    getActiveDates = () => {
        const { viewMode, weekStart, monthStart } = this.state;
        return viewMode === 'month' ? getMonthDates(monthStart) : getWeekDates(weekStart);
    }

    onViewModeChange = (mode) => {
        this.setState({ viewMode: mode }, () => this.fetchPeriodData());
    }

    onWeekChange = (offset) => {
        const { weekStart } = this.state;
        const d = new Date(weekStart + 'T00:00:00');
        d.setDate(d.getDate() + (offset * 7));
        this.setState({ weekStart: formatDateISO(d) }, () => this.fetchPeriodData());
    }

    onMonthChange = (offset) => {
        const { monthStart } = this.state;
        const [year, month] = monthStart.split('-').map(Number);
        const d = new Date(year, month - 1 + offset, 1);
        const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        this.setState({ monthStart: ym }, () => this.fetchPeriodData());
    }

    onGoToCurrentWeek = () => {
        this.setState({ weekStart: getMonday(getTodayDate()) }, () => this.fetchPeriodData());
    }

    onGoToCurrentMonth = () => {
        this.setState({ monthStart: getCurrentYearMonth() }, () => this.fetchPeriodData());
    }

    /**
     * Filter to only WORK type logs.
     * Work logs are those whose subProgramId belongs to a WORK-type program.
     */
    getWorkLogs = (logs) => {
        const { subPrograms, programs } = this.state;
        const workProgramIds = new Set(programs.filter(p => p.type === 'WORK').map(p => p.id));
        const workSubProgramIds = new Set(subPrograms.filter(sp => workProgramIds.has(sp.programId)).map(sp => sp.id));
        return logs.filter(log => workSubProgramIds.has(log.subProgramId));
    }

    getSubProgramName = (subProgramId) => {
        const sp = this.state.subPrograms.find(s => s.id === subProgramId);
        if (!sp) return 'Unknown';
        const prog = this.state.programs.find(p => p.id === sp.programId);
        return prog ? `${prog.name} | ${sp.name}` : sp.name;
    }

    getProgramName = (subProgramId) => {
        const sp = this.state.subPrograms.find(s => s.id === subProgramId);
        if (!sp) return 'Unknown';
        const prog = this.state.programs.find(p => p.id === sp.programId);
        return prog ? prog.name : 'Unknown';
    }

    getPersonName = (personId) => {
        if (!personId) return 'Me';
        const p = this.state.persons.find(per => per.id === personId);
        return p ? p.name : 'Unknown';
    }

    /**
     * Compute daily summaries:
     * - totalLoggedMinutes: sum of all individual log durations
     * - overallMinutes: from first startTime to last endTime (office hours span)
     * - logCount: number of logs
     */
    computeDailySummaries = () => {
        const { weekData } = this.state;
        const dates = this.getActiveDates();

        return dates.map((date, idx) => {
            const d = new Date(date + 'T00:00:00');
            const dayIndex = (d.getDay() + 6) % 7; // 0=Mon, 6=Sun
            const allLogs = weekData[date] || [];
            const workLogs = this.getWorkLogs(allLogs);

            if (workLogs.length === 0) {
                return { date, dayIndex, totalLoggedMinutes: 0, overallMinutes: 0, logCount: 0, firstStart: null, lastEnd: null };
            }

            // Total logged minutes (sum of each log's duration)
            const totalLoggedMinutes = workLogs.reduce((sum, log) => {
                const start = timeToMinutes(log.startTime);
                const end = timeToMinutes(log.endTime);
                let diff = end - start;
                if (diff <= 0) diff += 24 * 60;
                return sum + diff;
            }, 0);

            // Overall time: first start to last end
            const startTimes = workLogs.map(log => timeToMinutes(log.startTime));
            const endTimes = workLogs.map(log => timeToMinutes(log.endTime));
            const firstStart = Math.min(...startTimes);
            const lastEnd = Math.max(...endTimes);
            let overallMinutes = lastEnd - firstStart;
            if (overallMinutes <= 0) overallMinutes += 24 * 60;

            return { date, dayIndex, totalLoggedMinutes, overallMinutes, logCount: workLogs.length, firstStart, lastEnd };
        });
    }

    /**
     * Compute activity breakdown by sub-program for the entire week.
     * Returns { subProgramName: totalMinutes }
     */
    computeActivityBreakdown = () => {
        const { weekData } = this.state;
        const dates = this.getActiveDates();
        const breakdown = {};

        dates.forEach(date => {
            const allLogs = weekData[date] || [];
            const workLogs = this.getWorkLogs(allLogs);
            workLogs.forEach(log => {
                const name = this.getSubProgramName(log.subProgramId);
                const start = timeToMinutes(log.startTime);
                const end = timeToMinutes(log.endTime);
                let diff = end - start;
                if (diff <= 0) diff += 24 * 60;
                breakdown[name] = (breakdown[name] || 0) + diff;
            });
        });

        return breakdown;
    }

    /**
     * Compute people interaction: hours spent with each person across the week.
     * Logs without personId are "Me" (solo work).
     */
    computePeopleBreakdown = () => {
        const { weekData } = this.state;
        const dates = this.getActiveDates();
        const breakdown = {};

        dates.forEach(date => {
            const allLogs = weekData[date] || [];
            const workLogs = this.getWorkLogs(allLogs);
            workLogs.forEach(log => {
                const personName = this.getPersonName(log.personId);
                const start = timeToMinutes(log.startTime);
                const end = timeToMinutes(log.endTime);
                let diff = end - start;
                if (diff <= 0) diff += 24 * 60;
                breakdown[personName] = (breakdown[personName] || 0) + diff;
            });
        });

        return breakdown;
    }

    render() {
        const { isLoaded, isLoadingWeek, error, weekStart, viewMode, monthStart } = this.state;
        const weekDates = getWeekDates(weekStart);

        const styles = {
            page: {
                background: 'linear-gradient(135deg, #2d3748 0%, #1a202c 100%)',
                minHeight: '100vh',
                padding: '30px 0',
            },
            header: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                marginBottom: '24px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
            title: {
                fontSize: '2em',
                fontWeight: '800',
                background: 'linear-gradient(135deg, #2d3748, #4a5568)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                margin: 0,
            },
            controls: {
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                flexWrap: 'wrap',
                marginTop: '16px',
                padding: '16px 20px',
                background: 'linear-gradient(135deg, #f7fafc, #edf2f7)',
                borderRadius: '12px',
                border: '1px solid #e2e8f0',
            },
            section: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                marginBottom: '24px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
            toggleBtn: (active) => ({
                padding: '7px 16px',
                fontWeight: '600',
                fontSize: '0.85em',
                border: 'none',
                cursor: 'pointer',
                background: active ? 'linear-gradient(135deg, #4a5568, #2d3748)' : 'white',
                color: active ? 'white' : '#4a5568',
                transition: 'all 0.2s',
            }),
        };

        return (
            <div style={styles.page}>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="12">
                            {/* Header */}
                            <div style={styles.header}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
                                    <h1 style={styles.title}>📊 Work Report</h1>
                                    <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                                        {/* View mode toggle */}
                                        <div style={{ display: 'flex', borderRadius: '10px', overflow: 'hidden', border: '2px solid #e2e8f0' }}>
                                            <button onClick={() => this.onViewModeChange('week')} style={styles.toggleBtn(viewMode === 'week')}>📅 Week</button>
                                            <button onClick={() => this.onViewModeChange('month')} style={styles.toggleBtn(viewMode === 'month')}>🗓️ Month</button>
                                        </div>
                                        <CButton color="light" onClick={() => this.fetchPeriodData()} title="Refresh" style={{ borderRadius: '10px', fontWeight: '600', padding: '8px 14px' }}>🔄</CButton>
                                    </div>
                                </div>
                                <div style={styles.controls}>
                                    {viewMode === 'week' ? (
                                        <>
                                            <CButton size="sm" onClick={() => this.onWeekChange(-1)} style={{ borderRadius: '8px', fontWeight: '700', padding: '6px 12px', background: 'white', border: '2px solid #e2e8f0', color: '#4a5568' }}>◀</CButton>
                                            <span style={{ fontWeight: '700', color: '#4a5568', fontSize: '0.92em' }}>
                                                {formatDate(weekDates[0])} — {formatDate(weekDates[6])}
                                            </span>
                                            <CButton size="sm" onClick={() => this.onWeekChange(1)} style={{ borderRadius: '8px', fontWeight: '700', padding: '6px 12px', background: 'white', border: '2px solid #e2e8f0', color: '#4a5568' }}>▶</CButton>
                                            <CButton size="sm" onClick={this.onGoToCurrentWeek} style={{ borderRadius: '8px', fontWeight: '600', padding: '6px 14px', background: 'linear-gradient(135deg, #4a5568, #2d3748)', border: 'none', color: 'white' }}>This Week</CButton>
                                        </>
                                    ) : (
                                        <>
                                            <CButton size="sm" onClick={() => this.onMonthChange(-1)} style={{ borderRadius: '8px', fontWeight: '700', padding: '6px 12px', background: 'white', border: '2px solid #e2e8f0', color: '#4a5568' }}>◀</CButton>
                                            <span style={{ fontWeight: '700', color: '#4a5568', fontSize: '0.92em' }}>
                                                {formatYearMonth(monthStart)}
                                            </span>
                                            <CButton size="sm" onClick={() => this.onMonthChange(1)} style={{ borderRadius: '8px', fontWeight: '700', padding: '6px 12px', background: 'white', border: '2px solid #e2e8f0', color: '#4a5568' }}>▶</CButton>
                                            <CButton size="sm" onClick={this.onGoToCurrentMonth} style={{ borderRadius: '8px', fontWeight: '600', padding: '6px 14px', background: 'linear-gradient(135deg, #4a5568, #2d3748)', border: 'none', color: 'white' }}>This Month</CButton>
                                        </>
                                    )}
                                </div>
                            </div>

                            {!isLoaded && <Loading />}
                            {isLoaded && error && (
                                <div style={{ ...styles.section, textAlign: 'center', color: '#e53e3e' }}>
                                    <p>⚠️ Error: {error}</p>
                                </div>
                            )}
                            {isLoaded && !error && this.renderReport(isLoadingWeek)}
                        </CCol>
                    </CRow>
                </CContainer>
            </div>
        );
    }

    renderReport(isLoadingWeek) {
        const { viewMode } = this.state;
        const allDailySummaries = this.computeDailySummaries();
        const activityBreakdown = this.computeActivityBreakdown();
        const peopleBreakdown = this.computePeopleBreakdown();

        // Hide Sat/Sun if they have no logs
        const dailySummaries = allDailySummaries.filter((d) => {
            if ((d.dayIndex === 5 || d.dayIndex === 6) && d.logCount === 0) return false;
            return true;
        });

        const totalWeekLogged = dailySummaries.reduce((s, d) => s + d.totalLoggedMinutes, 0);
        const totalWeekOverall = dailySummaries.reduce((s, d) => s + d.overallMinutes, 0);

        const sectionStyle = {
            background: 'rgba(255, 255, 255, 0.95)',
            backdropFilter: 'blur(10px)',
            borderRadius: '16px',
            padding: '28px 32px',
            marginBottom: '24px',
            boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
            border: '1px solid rgba(255, 255, 255, 0.8)',
        };

        return (
            <div>
                {isLoadingWeek && (
                    <div style={{ textAlign: 'center', padding: '12px', color: '#4a5568', fontWeight: '600' }}>Loading week data...</div>
                )}

                {/* Section 1: Time Summary Table */}
                <div style={sectionStyle}>
                    <h3 style={{ fontWeight: '700', color: '#2d3748', marginBottom: '20px', fontSize: '1.2em' }}>⏱️ Daily Time Summary</h3>
                    <div style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: '700px' }}>
                            <thead>
                                <tr style={{ background: '#f7fafc', borderBottom: '2px solid #e2e8f0' }}>
                                    <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: '700', fontSize: '0.82em', color: '#4a5568', textTransform: 'uppercase' }}>Day</th>
                                    <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: '700', fontSize: '0.82em', color: '#4a5568', textTransform: 'uppercase' }}>Logged Time</th>
                                    <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: '700', fontSize: '0.82em', color: '#4a5568', textTransform: 'uppercase' }}>Overall (First→Last)</th>
                                    <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: '700', fontSize: '0.82em', color: '#4a5568', textTransform: 'uppercase' }}>Logs</th>
                                    <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: '700', fontSize: '0.82em', color: '#4a5568', textTransform: 'uppercase' }}>Window</th>
                                </tr>
                            </thead>
                            <tbody>
                                {dailySummaries.map((d, i) => {
                                    const isToday = d.date === getTodayDate();
                                    return (
                                        <tr key={d.date} style={{ borderBottom: '1px solid #edf2f7', background: isToday ? '#f0fff4' : (i % 2 === 0 ? '#fff' : '#f7fafc') }}>
                                            <td style={{ padding: '12px 16px', fontWeight: '600', color: '#2d3748' }}>
                                                {DAY_LABELS[d.dayIndex]} <span style={{ color: '#a0aec0', fontSize: '0.85em' }}>{formatDate(d.date)}</span>
                                                {isToday && <span style={{ marginLeft: '8px', fontSize: '0.75em', background: '#48bb78', color: 'white', padding: '2px 8px', borderRadius: '10px' }}>Today</span>}
                                            </td>
                                            <td style={{ padding: '12px 16px', textAlign: 'center', fontWeight: '700', color: d.totalLoggedMinutes > 0 ? '#2d3748' : '#cbd5e0', fontFamily: 'monospace' }}>
                                                {d.totalLoggedMinutes > 0 ? minutesToDisplay(d.totalLoggedMinutes) : '—'}
                                            </td>
                                            <td style={{ padding: '12px 16px', textAlign: 'center', fontWeight: '700', color: d.overallMinutes > 0 ? '#4a5568' : '#cbd5e0', fontFamily: 'monospace' }}>
                                                {d.overallMinutes > 0 ? minutesToDisplay(d.overallMinutes) : '—'}
                                            </td>
                                            <td style={{ padding: '12px 16px', textAlign: 'center', color: d.logCount > 0 ? '#4a5568' : '#cbd5e0' }}>{d.logCount || '—'}</td>
                                            <td style={{ padding: '12px 16px', textAlign: 'center', fontFamily: 'monospace', fontSize: '0.85em', color: '#718096' }}>
                                                {d.firstStart !== null ? `${String(Math.floor(d.firstStart / 60)).padStart(2, '0')}:${String(d.firstStart % 60).padStart(2, '0')} – ${String(Math.floor(d.lastEnd / 60)).padStart(2, '0')}:${String(d.lastEnd % 60).padStart(2, '0')}` : '—'}
                                            </td>
                                        </tr>
                                    );
                                })}
                                {/* Week total row */}
                                <tr style={{ background: 'linear-gradient(135deg, #edf2f7, #e2e8f0)', borderTop: '2px solid #cbd5e0' }}>
                                    <td style={{ padding: '14px 16px', fontWeight: '800', color: '#2d3748', fontSize: '0.95em' }}>{viewMode === 'month' ? '📅 Month Total' : '📅 Week Total'}</td>
                                    <td style={{ padding: '14px 16px', textAlign: 'center', fontWeight: '800', color: '#2d3748', fontFamily: 'monospace', fontSize: '1.05em' }}>{minutesToDisplay(totalWeekLogged)}</td>
                                    <td style={{ padding: '14px 16px', textAlign: 'center', fontWeight: '800', color: '#4a5568', fontFamily: 'monospace', fontSize: '1.05em' }}>{minutesToDisplay(totalWeekOverall)}</td>
                                    <td style={{ padding: '14px 16px', textAlign: 'center', fontWeight: '700', color: '#4a5568' }}>{dailySummaries.reduce((s, d) => s + d.logCount, 0)}</td>
                                    <td style={{ padding: '14px 16px' }}></td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Section 2: Bar chart - Daily logged time */}
                <div style={sectionStyle}>
                    <h3 style={{ fontWeight: '700', color: '#2d3748', marginBottom: '20px', fontSize: '1.2em' }}>📈 Daily Hours (Bar Chart)</h3>
                    {this.renderDailyBarChart(dailySummaries)}
                </div>

                {/* Section 3: Pie chart - Activity breakdown */}
                <div style={sectionStyle}>
                    <h3 style={{ fontWeight: '700', color: '#2d3748', marginBottom: '20px', fontSize: '1.2em' }}>🧩 Activity Breakdown</h3>
                    <div style={{ marginBottom: '24px' }}>
                        {this.renderActivityPieChart(activityBreakdown)}
                    </div>
                    <div>
                        {this.renderActivityBarChart(activityBreakdown)}
                    </div>
                </div>

                {/* Section 4: Pie chart - People interactions */}
                <div style={sectionStyle}>
                    <h3 style={{ fontWeight: '700', color: '#2d3748', marginBottom: '20px', fontSize: '1.2em' }}>👥 People Interactions</h3>
                    {this.renderPeoplePieChart(peopleBreakdown)}
                </div>

                {/* Section 5: Weekly Activity Heatmap */}
                <div style={sectionStyle}>
                    <h3 style={{ fontWeight: '700', color: '#2d3748', marginBottom: '20px', fontSize: '1.2em' }}>🔥 Weekly Activity Heatmap</h3>
                    <p style={{ color: '#718096', fontSize: '0.85em', marginBottom: '16px' }}>Hover over a colored block to see task details. X-axis = time of day, Y-axis = day/date.</p>
                    {this.renderWeeklyActivityHeatmap()}
                </div>
            </div>
        );
    }

    renderWeeklyActivityHeatmap() {
        const { weekData } = this.state;
        const allDates = this.getActiveDates();

        // Filter out weekend days if they have no work logs
        const filteredDays = allDates.map((date, i) => {
            const d = new Date(date + 'T00:00:00');
            const dayIndex = (d.getDay() + 6) % 7; // 0=Mon, 6=Sun
            return { date, dayIndex };
        }).filter(({ date, dayIndex }) => {
            if (dayIndex >= 5) {
                const allLogs = weekData[date] || [];
                const workLogs = this.getWorkLogs(allLogs);
                return workLogs.length > 0;
            }
            return true;
        });

        // If no work logs exist at all, show empty state
        const hasAnyData = filteredDays.some(({ date }) => {
            const allLogs = weekData[date] || [];
            return this.getWorkLogs(allLogs).length > 0;
        });
        if (!hasAnyData) {
            return (
                <div style={{ textAlign: 'center', padding: '60px 40px', color: '#a0aec0' }}>
                    <div style={{ fontSize: '3em', marginBottom: '12px' }}>📭</div>
                    <p style={{ fontStyle: 'italic', fontSize: '1.1em', fontWeight: '500' }}>No work activity logged for this period.</p>
                </div>
            );
        }

        // Build a heatmap: rows (filtered days) x 48 columns (30-min slots)
        const SLOTS = 48; // 30-min intervals across 24h
        const slotLabels = [];
        for (let s = 0; s < SLOTS; s++) {
            const h = Math.floor(s / 2);
            const m = (s % 2) * 30;
            slotLabels.push(`${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`);
        }

        const yLabels = filteredDays.map(({ date, dayIndex }) => {
            const d = new Date(date + 'T00:00:00');
            return `${DAY_LABELS[dayIndex]} ${d.getDate()}/${d.getMonth() + 1}`;
        });

        // z[day][slot] = minutes of work in that slot
        const z = [];
        const hoverTexts = [];

        filteredDays.forEach(({ date }) => {
            const allLogs = weekData[date] || [];
            const workLogs = this.getWorkLogs(allLogs);
            const row = new Array(SLOTS).fill(0);
            const hoverRow = new Array(SLOTS).fill('');

            workLogs.forEach(log => {
                if (!log.startTime || !log.endTime) return;
                const startMin = timeToMinutes(log.startTime);
                const endMin = timeToMinutes(log.endTime);
                let adjustedEnd = endMin;
                if (adjustedEnd <= startMin) adjustedEnd += 24 * 60;

                const taskName = this.getSubProgramName(log.subProgramId);
                const personName = this.getPersonName(log.personId);
                const title = log.title || '(no title)';
                const duration = minutesToDisplay(adjustedEnd - startMin);
                const timeStr = `${log.startTime.substring(0,2)}:${log.startTime.substring(2)} – ${log.endTime.substring(0,2)}:${log.endTime.substring(2)}`;

                // Distribute into 30-min slots
                for (let s = 0; s < SLOTS; s++) {
                    const slotStart = s * 30;
                    const slotEnd = (s + 1) * 30;
                    const overlapStart = Math.max(startMin, slotStart);
                    const overlapEnd = Math.min(adjustedEnd, slotEnd);
                    if (overlapEnd > overlapStart) {
                        row[s] += (overlapEnd - overlapStart);
                        // Append task info to hover
                        const existing = hoverRow[s];
                        const taskInfo = `${title} | ${taskName}<br>👤 ${personName} | ⏱️ ${timeStr} (${duration})`;
                        hoverRow[s] = existing ? existing + '<br>---<br>' + taskInfo : taskInfo;
                    }
                }
            });

            z.push(row);
            hoverTexts.push(hoverRow.map(text => text || 'No activity'));
        });

        // Build vertical line shapes at every hour (every 2 slots)
        const hourlyLines = [];
        for (let h = 1; h < 24; h++) {
            hourlyLines.push({
                type: 'line',
                x0: h * 2 - 0.5,
                x1: h * 2 - 0.5,
                y0: -0.5,
                y1: filteredDays.length - 0.5,
                xref: 'x',
                yref: 'y',
                line: { color: 'rgba(45, 55, 72, 0.3)', width: 1, dash: 'dot' },
            });
        }

        return (
            <Plot
                data={[{
                    z: z,
                    x: slotLabels,
                    y: yLabels,
                    type: 'heatmap',
                    colorscale: [
                        [0, '#f7fafc'],
                        [0.01, '#e8ecff'],
                        [0.25, '#b3c4ff'],
                        [0.5, '#667eea'],
                        [0.75, '#5a4fcf'],
                        [1, '#3c366b'],
                    ],
                    hoverinfo: 'text',
                    text: hoverTexts,
                    hovertemplate: '<b>%{y}</b> | %{x}<br><br>%{text}<extra></extra>',
                    showscale: true,
                    colorbar: {
                        title: 'Minutes',
                        titleside: 'right',
                        thickness: 15,
                        len: 0.8,
                    },
                    xgap: 1,
                    ygap: 3,
                }]}
                layout={{
                    margin: { t: 30, b: 60, l: 100, r: 80 },
                    xaxis: {
                        title: 'Time of Day',
                        tickangle: -45,
                        dtick: 2,
                        showgrid: false,
                    },
                    yaxis: {
                        title: '',
                        autorange: 'reversed',
                        showgrid: false,
                    },
                    shapes: hourlyLines,
                    plot_bgcolor: '#fafbff',
                    paper_bgcolor: 'transparent',
                    font: { family: 'inherit', size: 11, color: '#4a5568' },
                    height: Math.max(200, filteredDays.length * 50 + 90),
                    hoverlabel: {
                        bgcolor: '#2d3748',
                        font: { color: 'white', size: 12 },
                        align: 'left',
                    },
                }}
                config={{ displayModeBar: false, responsive: true }}
                style={{ width: '100%' }}
            />
        );
    }

    renderDailyBarChart(dailySummaries) {
        const labels = dailySummaries.map(d => {
            const dt = new Date(d.date + 'T00:00:00');
            return `${DAY_LABELS[d.dayIndex]} ${dt.getDate()}/${dt.getMonth() + 1}`;
        });
        const loggedHours = dailySummaries.map(d => minutesToHours(d.totalLoggedMinutes));
        const overallHours = dailySummaries.map(d => minutesToHours(d.overallMinutes));
        const dynamicHeight = Math.max(320, 200 + labels.length * 20);

        return (
            <Plot
                data={[
                    {
                        x: labels,
                        y: loggedHours,
                        type: 'bar',
                        name: 'Logged Time',
                        marker: { color: '#667eea' },
                        text: loggedHours.map(h => h > 0 ? h.toFixed(1) + 'h' : ''),
                        textposition: 'outside',
                    },
                    {
                        x: labels,
                        y: overallHours,
                        type: 'bar',
                        name: 'Overall (First→Last)',
                        marker: { color: '#a0aec0' },
                        text: overallHours.map(h => h > 0 ? h.toFixed(1) + 'h' : ''),
                        textposition: 'outside',
                    },
                ]}
                layout={{
                    barmode: 'group',
                    margin: { t: 30, b: 60, l: 50, r: 20 },
                    yaxis: { title: 'Hours', gridcolor: '#edf2f7' },
                    xaxis: { title: '', tickangle: labels.length > 10 ? -45 : 0 },
                    legend: { orientation: 'h', y: -0.2 },
                    plot_bgcolor: '#fafbff',
                    paper_bgcolor: 'transparent',
                    font: { family: 'inherit', size: 12, color: '#4a5568' },
                    height: dynamicHeight,
                }}
                config={{ displayModeBar: false, responsive: true }}
                style={{ width: '100%' }}
            />
        );
    }

    renderActivityPieChart(activityBreakdown) {
        const entries = Object.entries(activityBreakdown).sort((a, b) => b[1] - a[1]);
        if (entries.length === 0) {
            return <p style={{ color: '#a0aec0', textAlign: 'center', padding: '40px' }}>No activity data</p>;
        }

        const labels = entries.map(([name]) => name);
        const values = entries.map(([, mins]) => minutesToHours(mins));
        const dynamicHeight = Math.max(400, 300 + entries.length * 25);

        return (
            <Plot
                data={[{
                    labels,
                    values,
                    type: 'pie',
                    hole: 0.4,
                    textinfo: 'label+percent',
                    textposition: 'outside',
                    marker: {
                        colors: ['#667eea', '#48bb78', '#ed64a6', '#f6ad55', '#4299e1', '#9f7aea', '#38b2ac', '#fc8181', '#68d391', '#a78bfa'],
                    },
                }]}
                layout={{
                    margin: { t: 40, b: 40, l: 40, r: 40 },
                    showlegend: true,
                    legend: { orientation: 'h', y: -0.15 },
                    plot_bgcolor: 'transparent',
                    paper_bgcolor: 'transparent',
                    font: { family: 'inherit', size: 11, color: '#4a5568' },
                    height: dynamicHeight,
                }}
                config={{ displayModeBar: false, responsive: true }}
                style={{ width: '100%' }}
            />
        );
    }

    renderActivityBarChart(activityBreakdown) {
        const entries = Object.entries(activityBreakdown).sort((a, b) => b[1] - a[1]);
        if (entries.length === 0) {
            return <p style={{ color: '#a0aec0', textAlign: 'center', padding: '40px' }}>No activity data</p>;
        }

        const labels = entries.map(([name]) => name);
        const values = entries.map(([, mins]) => minutesToHours(mins));
        const dynamicHeight = Math.max(300, 100 + entries.length * 40);

        return (
            <Plot
                data={[{
                    y: labels,
                    x: values,
                    type: 'bar',
                    orientation: 'h',
                    marker: {
                        color: values.map((_, i) => ['#667eea', '#48bb78', '#ed64a6', '#f6ad55', '#4299e1', '#9f7aea', '#38b2ac', '#fc8181', '#68d391', '#a78bfa'][i % 10]),
                    },
                    text: values.map(v => v.toFixed(1) + 'h'),
                    textposition: 'outside',
                }]}
                layout={{
                    margin: { t: 20, b: 40, l: 180, r: 60 },
                    xaxis: { title: 'Hours', gridcolor: '#edf2f7' },
                    yaxis: { autorange: 'reversed' },
                    plot_bgcolor: '#fafbff',
                    paper_bgcolor: 'transparent',
                    font: { family: 'inherit', size: 11, color: '#4a5568' },
                    height: dynamicHeight,
                }}
                config={{ displayModeBar: false, responsive: true }}
                style={{ width: '100%' }}
            />
        );
    }

    renderPeoplePieChart(peopleBreakdown) {
        const entries = Object.entries(peopleBreakdown).sort((a, b) => b[1] - a[1]);
        if (entries.length === 0) {
            return <p style={{ color: '#a0aec0', textAlign: 'center', padding: '40px' }}>No interaction data</p>;
        }

        const labels = entries.map(([name]) => name);
        const values = entries.map(([, mins]) => minutesToHours(mins));
        const dynamicHeight = Math.max(400, 300 + entries.length * 25);

        return (
            <Plot
                data={[{
                    labels,
                    values,
                    type: 'pie',
                    hole: 0.35,
                    textinfo: 'label+value',
                    textposition: 'outside',
                    hovertemplate: '%{label}: %{value:.1f}h (%{percent})<extra></extra>',
                    marker: {
                        colors: ['#4299e1', '#48bb78', '#ed64a6', '#f6ad55', '#9f7aea', '#667eea', '#38b2ac', '#fc8181', '#68d391', '#a78bfa'],
                    },
                }]}
                layout={{
                    margin: { t: 40, b: 40, l: 40, r: 40 },
                    showlegend: true,
                    legend: { orientation: 'h', y: -0.15 },
                    plot_bgcolor: 'transparent',
                    paper_bgcolor: 'transparent',
                    font: { family: 'inherit', size: 12, color: '#4a5568' },
                    height: dynamicHeight,
                }}
                config={{ displayModeBar: false, responsive: true }}
                style={{ width: '100%' }}
            />
        );
    }
}

export default WorkReport;
